#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_FIELDS 32
#define FIELD_SECRET 0x01
#define FIELD_NORMAL 0x00

typedef struct {
    char *name;
    char *value;
    int flags;
    size_t value_len;
} field_t;

typedef struct {
    field_t fields[MAX_FIELDS];
    int field_count;
    char *serialized_buf;
    size_t serialized_len;
    int finalized;
} serializer_t;

static volatile sig_atomic_t g_shutdown_requested = 0;
static serializer_t *g_active_serializer = NULL;
static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;

static void shutdown_handler(int sig) {
    (void)sig;
    g_shutdown_requested = 1;
}

static int scrub_field(field_t *f) {
    if (f->value && (f->flags & FIELD_SECRET)) {
        memset(f->value, 0, f->value_len);
    }
    return 0;
}

static void cleanup_serializer(serializer_t *s) {
    if (!s) return;
    for (int i = 0; i < s->field_count; i++) {
        scrub_field(&s->fields[i]);
        free(s->fields[i].name);
        free(s->fields[i].value);
    }
    if (s->serialized_buf) {
        free(s->serialized_buf);
        s->serialized_buf = NULL;
    }
}

serializer_t *serializer_create(void) {
    serializer_t *s = calloc(1, sizeof(serializer_t));
    if (!s) return NULL;
    pthread_mutex_lock(&g_mutex);
    g_active_serializer = s;
    pthread_mutex_unlock(&g_mutex);
    return s;
}

int serializer_add_field(serializer_t *s, const char *name, const char *value, int flags) {
    if (!s || s->field_count >= MAX_FIELDS) return -1;
    if (s->finalized) return -1;

    int idx = s->field_count;
    s->fields[idx].name = strdup(name);
    s->fields[idx].value = strdup(value);
    s->fields[idx].value_len = strlen(value);
    s->fields[idx].flags = flags;
    s->field_count++;
    return 0;
}

static size_t compute_serialized_size(serializer_t *s) {
    size_t total = 4; /* header */
    for (int i = 0; i < s->field_count; i++) {
        if (s->fields[i].flags & FIELD_SECRET) continue;
        total += strlen(s->fields[i].name) + 1;
        total += s->fields[i].value_len + 1;
        total += 4; /* length prefix */
    }
    return total;
}

int serializer_finalize(serializer_t *s) {
    if (!s || s->finalized) return -1;

    size_t buf_size = compute_serialized_size(s);
    s->serialized_buf = malloc(buf_size);
    if (!s->serialized_buf) return -1;

    char *ptr = s->serialized_buf;
    memcpy(ptr, "SER1", 4);
    ptr += 4;

    for (int i = 0; i < s->field_count; i++) {
        if (g_shutdown_requested) {
            /* Graceful shutdown: finalize what we have */
            s->finalized = 1;
            s->serialized_len = ptr - s->serialized_buf;
            return 1; /* partial */
        }
        if (s->fields[i].flags & FIELD_SECRET) continue;

        size_t nlen = strlen(s->fields[i].name);
        memcpy(ptr, &nlen, 4);
        ptr += 4;
        memcpy(ptr, s->fields[i].name, nlen);
        ptr += nlen;
        *ptr++ = '=';
        memcpy(ptr, s->fields[i].value, s->fields[i].value_len);
        ptr += s->fields[i].value_len;
        *ptr++ = '\0';
    }

    s->finalized = 1;
    s->serialized_len = ptr - s->serialized_buf;
    return 0;
}

const char *serializer_get_output(serializer_t *s, size_t *out_len) {
    if (!s || !s->finalized) return NULL;
    if (out_len) *out_len = s->serialized_len;
    return s->serialized_buf;
}

void serializer_destroy(serializer_t *s) {
    if (!s) return;
    pthread_mutex_lock(&g_mutex);
    if (g_active_serializer == s)
        g_active_serializer = NULL;
    pthread_mutex_unlock(&g_mutex);
    cleanup_serializer(s);
    free(s);
}

/* Graceful shutdown thread - runs cleanup on SIGTERM */
static void *shutdown_monitor(void *arg) {
    (void)arg;
    while (!g_shutdown_requested) {
        usleep(100000);
    }
    pthread_mutex_lock(&g_mutex);
    if (g_active_serializer && !g_active_serializer->finalized) {
        /* Force finalization to flush output before exit */
        serializer_finalize(g_active_serializer);
    }
    pthread_mutex_unlock(&g_mutex);
    return NULL;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = shutdown_handler;
    sigaction(SIGTERM, &sa, NULL);
    sigaction(SIGINT, &sa, NULL);

    pthread_t monitor_tid;
    pthread_create(&monitor_tid, NULL, shutdown_monitor, NULL);

    serializer_t *s = serializer_create();
    serializer_add_field(s, "username", "admin", FIELD_NORMAL);
    serializer_add_field(s, "api_key", "sk-live-9f8a7b6c5d4e3f2a1b0c", FIELD_SECRET);
    serializer_add_field(s, "session", "abc123", FIELD_NORMAL);
    serializer_add_field(s, "db_password", "SuperS3cret!Pass", FIELD_SECRET);
    serializer_add_field(s, "endpoint", "https://api.example.com", FIELD_NORMAL);

    int rc = serializer_finalize(s);

    size_t out_len;
    const char *output = serializer_get_output(s, &out_len);
    if (output) {
        write(STDOUT_FILENO, output, out_len);
    }

    serializer_destroy(s);
    g_shutdown_requested = 1;
    pthread_join(monitor_tid, NULL);
    return rc;
}
